package palindrome

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// Product represents a palindromic product and its factorizations.
type Product struct {
	Value         int
	Factorizations [][2]int
}

// Products returns the smallest and largest palindromic products
// of two factors in the range [fmin, fmax], along with all of their
// factor pairs within the range.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, fmt.Errorf("fmin > fmax: %d > %d", fmin, fmax)
	}

	var min, max Product
	found := false

	for a := fmin; a <= fmax; a++ {
		for b := a; b <= fmax; b++ {
			p := a * b
			if !isPalindrome(p) {
				continue
			}
			pair := [2]int{a, b}
			if !found || p < min.Value {
				min = Product{p, [][2]int{pair}}
				found = true
			} else if p == min.Value {
				min.Factorizations = append(min.Factorizations, pair)
			}
			if !found || p > max.Value {
				max = Product{p, [][2]int{pair}}
				found = true
			} else if p == max.Value {
				max.Factorizations = append(max.Factorizations, pair)
			}
		}
	}

	if !found {
		return Product{}, Product{}, errors.New("no palindromes found in the given range")
	}
	return min, max, nil
}

func isPalindrome(n int) bool {
	s := strconv.Itoa(n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}
